const input = $json.body || $json;

const required = ['avatar', 'scene', 'assetType'];
const missing = required.filter(k => !input[k]);

if (missing.length > 0) {
  throw new Error(`Missing required fields: ${missing.join(', ')}`);
}

return [{
  json: {
    avatar: input.avatar,
    scene: input.scene,
    assetType: input.assetType,
    baseUrl: input.baseUrl || 'http://192.168.0.194:9000'
  }
}];

const params = $('Normalize Query').first().json;
const asset = $input.first().json;

if (!asset || !asset.asset_id) {
  return [{
    json: {
      found: false,
      avatar: params.avatar,
      scene: params.scene,
      assetType: params.assetType,
      reason: 'No canonical asset found'
    }
  }];
}

return [{
  json: {
    found: true,
    assetId: asset.asset_id,
    avatar: asset.avatar,
    scene: asset.scene,
    assetType: asset.asset_type,
    url: `${params.baseUrl}/${asset.bucket}/${asset.object_path}`,
    bucket: asset.bucket,
    objectPath: asset.object_path,
    mimeType: asset.mime_type,
    status: asset.status,
    sha256: asset.sha256,
    canonicalGroup: asset.canonical_group,
    reviewNotes: asset.review_notes,
    createdAt: asset.created_at
  }
}];
